parts.text:
Now I have everything. Here's the full interface design with spec files.

---

## Interface Design: React Query Hooks

### Architecture

```
src/lib/
├── queryClient.ts          # QueryClient instance + fetchJSON adapter
├── direction.ts            # getDirection() — one correct implementation
└── queries/
    ├── accounts.ts         # useAccounts, useCreateAccount, useDeposit
    ├── transactions.ts     # useTransactions, useTransfer
    ├── ledger.ts           # useLedgerEntries
    ├── notifications.ts    # useNotifications, useDismissNotification, useMarkNotificationRead
    └── notificationPrefs.ts # useNotificationPrefs, useTogglePreference
```

---

### 1. `src/lib/queryClient.ts`

```ts
import { QueryClient } from "@tanstack/react-query"
import type { WaveResponse } from "@/types"

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000,       // 30s — data is fresh for 30s
      gcTime: 5 * 60_000,      // 5min — garbage collect after 5min
      retry: 1,                // one retry on failure
      refetchOnWindowFocus: false, // financial app — don't surprise-refetch
    },
  },
})

/**
 * Thin adapter over fetch that unwraps WaveResponse<T>.
 * Throws on ok:false so React Query treats it as an error.
 */
export async function fetchJSON<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  const json: WaveResponse<T> = await res.json()
  if (!json.ok) throw new Error(json.message)
  return json.data
}
```

**Spec: `src/lib/__tests__/queryClient.spec.ts`**

```ts
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { fetchJSON } from "../queryClient"

describe("fetchJSON", () => {
  let mockFetch: ReturnType<typeof vi.fn>

  beforeEach(() => {
    mockFetch = vi.fn()
    vi.stubGlobal("fetch", mockFetch)
  })

  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it("returns data on success", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: true, status: 200, message: "OK", data: { id: 1 } }),
    })

    const result = await fetchJSON("/api/test")
    expect(result).toEqual({ id: 1 })
  })

  it("throws on ok:false", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: false, status: 400, message: "Bad request", error: "invalid" }),
    })

    await expect(fetchJSON("/api/test")).rejects.toThrow("Bad request")
  })

  it("throws on network error", async () => {
    mockFetch.mockRejectedValue(new Error("Network error"))

    await expect(fetchJSON("/api/test")).rejects.toThrow("Network error")
  })

  it("passes init to fetch", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: true, status: 200, message: "OK", data: null }),
    })

    await fetchJSON("/api/test", { method: "POST", body: '{"a":1}' })

    expect(mockFetch).toHaveBeenCalledWith("/api/test", { method: "POST", body: '{"a":1}' })
  })
})
```

---

### 2. `src/lib/direction.ts`

```ts
import type { ITransaction } from "@/types"

export type Direction = "in" | "out" | "self"

/**
 * Determines whether a transaction is incoming, outgoing, or a self-transfer
 * relative to the user's accounts.
 *
 * @param tx - The transaction to classify
 * @param userAccountNumbers - Set of the user's account numbers (as strings)
 * @returns "in" if money came in, "out" if money went out, "self" if same account
 */
export function getDirection(
  tx: ITransaction,
  userAccountNumbers: Set<string>,
): Direction {
  const sender = String(tx.senderAccountNumber)
  const receiver = String(tx.receiverAccountNumber)

  if (sender === receiver) return "self"

  const senderIsUser = userAccountNumbers.has(sender)
  const receiverIsUser = userAccountNumbers.has(receiver)

  if (receiverIsUser && !senderIsUser) return "in"
  return "out"
}
```

**Spec: `src/lib/__tests__/direction.spec.ts`**

```ts
import { describe, it, expect } from "vitest"
import { getDirection, type Direction } from "../direction"
import type { ITransaction } from "@/types"

function tx(overrides: Partial<ITransaction> = {}): ITransaction {
  return {
    id: "tx_1" as any,
    amount: "100",
    userId: "user_1",
    senderAccountNumber: "1000000000001" as any,
    senderName: "Alice",
    receiverAccountNumber: "1000000000002" as any,
    receiverName: "Bob",
    status: "success",
    createdAt: new Date().toISOString(),
    updatedAt: null,
    ...overrides,
  }
}

describe("getDirection", () => {
  it("returns 'self' when sender equals receiver", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000001" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("self")
  })

  it("returns 'in' when receiver is user and sender is not", () => {
    const t = tx({
      senderAccountNumber: "1000000000099" as any,
      receiverAccountNumber: "1000000000001" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("in")
  })

  it("returns 'out' when sender is user and receiver is not", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000099" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("returns 'out' when both sender and receiver are user accounts", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000002" as any,
    })
    expect(getDirection(t, new Set(["1000000000001", "1000000000002"]))).toBe("out")
  })

  it("returns 'out' when neither account belongs to user", () => {
    const t = tx({
      senderAccountNumber: "1000000000098" as any,
      receiverAccountNumber: "1000000000099" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("handles numeric account numbers by converting to string", () => {
    const t = tx({
      senderAccountNumber: 1000000000001 as any,
      receiverAccountNumber: 1000000000002 as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("handles bigint account numbers", () => {
    const t = tx({
      senderAccountNumber: BigInt("1000000000001") as any,
      receiverAccountNumber: BigInt("1000000000002") as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })
})
```

