// ─── Query Keys ───────────────────────────────────────────────
export const notificationKeys = {
  all: ["notifications"] as const,
  user: (userId: string) => ["notifications", userId] as const,
}

// ─── Queries ──────────────────────────────────────────────────

/** Fetch notifications for a user */
export function useNotifications(userId: string, limit = 50) {
  return useQuery({
    queryKey: [...notificationKeys.user(userId), { limit }],
    queryFn: () =>
      fetchJSON<Notification[]>(
        `/api/notification/users/${userId}/notifications?limit=${limit}`,
      ),
    enabled: !!userId,
  })
}

// ─── Mutations ────────────────────────────────────────────────

/** Dismiss (delete) a notification */
export function useDismissNotification(userId: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (notificationId: string) =>
      fetchJSON<void>(
        `/api/notification/users/${userId}/notifications/${notificationId}`,
        { method: "DELETE" },
      ),
    onMutate: async (notificationId) => {
      await queryClient.cancelQueries({ queryKey: notificationKeys.user(userId) })
      const previous = queryClient.getQueryData<Notification[]>(
        notificationKeys.user(userId),
      )
      queryClient.setQueryData<Notification[]>(
        notificationKeys.user(userId),
        (old) => old?.filter((n) => n.id !== notificationId) ?? [],
      )
      return { previous }
    },
    onError: (_err, _vars, context) => {
      if (context?.previous) {
        queryClient.setQueryData(notificationKeys.user(userId), context.previous)
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: notificationKeys.user(userId) })
    },
  })
}

/** Mark a notification as read */
export function useMarkNotificationRead(userId: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (notificationId: string) =>
      fetchJSON<void>(
        `/api/notification/users/${userId}/notifications/${notificationId}/read`,
        { method: "PATCH" },
      ),
    onMutate: async (notificationId) => {
      await queryClient.cancelQueries({ queryKey: notificationKeys.user(userId) })
      const previous = queryClient.getQueryData<Notification[]>(
        notificationKeys.user(userId),
      )
      queryClient.setQueryData<Notification[]>(
        notificationKeys.user(userId),
        (old) =>
          old?.map((n) => (n.id === notificationId ? { ...n, read: true } : n)) ?? [],
      )
      return { previous }
    },
    onError: (_err, _vars, context) => {
      if (context?.previous) {
        queryClient.setQueryData(notificationKeys.user(userId), context.previous)
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: notificationKeys.user(userId) })
    },
  })
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"
import { fetchJSON } from "../queryClient"

// ─── Types ────────────────────────────────────────────────────
export interface NotificationPreference {
  id: string
  userId: string
  eventType: string
  enabled: boolean
}

// ─── Query Keys ───────────────────────────────────────────────
export const notificationPrefsKeys = {
  all: ["notificationPrefs"] as const,
  user: (userId: string) => ["notificationPrefs", userId] as const,
}

// ─── Queries ──────────────────────────────────────────────────

export function useNotificationPrefs(userId: string) {
  return useQuery({
    queryKey: notificationPrefsKeys.user(userId),
    queryFn: () =>
      fetchJSON<NotificationPreference[]>(
        `/api/notification/users/${userId}/notification-preferences`,
      ),
    enabled: !!userId,
  })
}

// ─── Mutations ────────────────────────────────────────────────

export function useTogglePreference(userId: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (input: { eventType: string; enabled: boolean }) =>
      fetchJSON<NotificationPreference>(
        `/api/notification/users/${userId}/notification-preferences`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(input),
        },
      ),
    onMutate: async (input) => {
      await queryClient.cancelQueries({ queryKey: notificationPrefsKeys.user(userId) })
      const previous = queryClient.getQueryData<NotificationPreference[]>(
        notificationPrefsKeys.user(userId),
      )
      queryClient.setQueryData<NotificationPreference[]>(
        notificationPrefsKeys.user(userId),
        (old) => {
          if (!old) return old
          const idx = old.findIndex((p) => p.eventType === input.eventType)
          if (idx >= 0) {
            const next = [...old]
            next[idx] = { ...next[idx], enabled: input.enabled }
            return next
          }
          return [...old, { id: "temp", userId, eventType: input.eventType, enabled: input.enabled }]
        },
      )
      return { previous }
    },
    onError: (_err, _vars, context) => {
      if (context?.previous) {
        queryClient.setQueryData(notificationPrefsKeys.user(userId), context.previous)
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: notificationPrefsKeys.user(userId) })
    },
  })
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { fetchJSON } from "../queryClient"

describe("fetchJSON", () => {
  let mockFetch: ReturnType<typeof vi.fn>

  beforeEach(() => {
    mockFetch = vi.fn()
    vi.stubGlobal("fetch", mockFetch)
  })

  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it("returns data on success", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: true, status: 200, message: "OK", data: { id: 1 } }),
    })

    const result = await fetchJSON("/api/test")
    expect(result).toEqual({ id: 1 })
  })

  it("throws on ok:false", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: false, status: 400, message: "Bad request", error: "invalid" }),
    })

    await expect(fetchJSON("/api/test")).rejects.toThrow("Bad request")
  })

  it("throws on network error", async () => {
    mockFetch.mockRejectedValue(new Error("Network error"))

    await expect(fetchJSON("/api/test")).rejects.toThrow("Network error")
  })

  it("passes init to fetch", async () => {
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: true, status: 200, message: "OK", data: null }),
    })

    await fetchJSON("/api/test", { method: "POST", body: '{"a":1}' })

    expect(mockFetch).toHaveBeenCalledWith("/api/test", { method: "POST", body: '{"a":1}' })
  })

  it("handles array data", async () => {
    const data = [{ id: 1 }, { id: 2 }]
    mockFetch.mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ ok: true, status: 200, message: "OK", data }),
    })

    const result = await fetchJSON("/api/items")
    expect(result).toEqual(data)
  })
})

import { describe, it, expect } from "vitest"
import { getDirection } from "../direction"
import type { ITransaction } from "@/types"

function tx(overrides: Partial<ITransaction> = {}): ITransaction {
  return {
    id: "tx_1" as any,
    amount: "100",
    userId: "user_1",
    senderAccountNumber: "1000000000001" as any,
    senderName: "Alice",
    receiverAccountNumber: "1000000000002" as any,
    receiverName: "Bob",
    status: "success",
    createdAt: new Date().toISOString(),
    updatedAt: null,
    ...overrides,
  }
}

describe("getDirection", () => {
  it("returns 'self' when sender equals receiver", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000001" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("self")
  })

  it("returns 'in' when receiver is user and sender is not", () => {
    const t = tx({
      senderAccountNumber: "1000000000099" as any,
      receiverAccountNumber: "1000000000001" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("in")
  })

  it("returns 'out' when sender is user and receiver is not", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000099" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("returns 'out' when both sender and receiver are user accounts", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000002" as any,
    })
    expect(getDirection(t, new Set(["1000000000001", "1000000000002"]))).toBe("out")
  })

  it("returns 'out' when neither account belongs to user", () => {
    const t = tx({
      senderAccountNumber: "1000000000098" as any,
      receiverAccountNumber: "1000000000099" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("handles numeric account numbers by converting to string", () => {
    const t = tx({
      senderAccountNumber: 1000000000001 as any,
      receiverAccountNumber: 1000000000002 as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("handles bigint account numbers", () => {
    const t = tx({
      senderAccountNumber: BigInt("1000000000001") as any,
      receiverAccountNumber: BigInt("1000000000002") as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("out")
  })

  it("returns 'in' for self-deposit (sender===receiver) even if in user set", () => {
    const t = tx({
      senderAccountNumber: "1000000000001" as any,
      receiverAccountNumber: "1000000000001" as any,
    })
    expect(getDirection(t, new Set(["1000000000001"]))).toBe("self")
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
