export const performanceRoutes = {
  /** Max throughput benchmark — sequential single-threaded transfers */
  benchmarkTransfers: "/benchmark/transfers",
  /** Get user's accounts for benchmark configuration */
  benchmarkAccounts: "/benchmark/accounts",
} as const;

import type { FastifyReply, FastifyRequest } from "fastify";
import { sendSuccess, sendError } from "@/lib/response";
import { WalletService } from "@/modules/wallet/service/wallet-service";
import type { TBankAccountNumber, TUserId } from "@/types";
import type { TransferInput } from "@/modules/wallet/service/wallet-service.interface";

const walletService = new WalletService();

// ─── Benchmark Types ────────────────────────────────────────────

interface BenchmarkConfig {
  userId: string;
  accountPairs: Array<{
    senderAccountNumber: string;
    senderName: string;
    receiverAccountNumber: string;
    receiverName: string;
  }>;
  numTransactions: number;
  amountPerTransaction: number;
}

interface LatencyStats {
  min: number;
  max: number;
  avg: number;
  p50: number;
  p95: number;
  p99: number;
}

interface BenchmarkResult {
  config: {
    numTransactions: number;
    amountPerTransaction: number;
    accountPairsCount: number;
  };
  summary: {
    totalTimeMs: number;
    transactionsPerSecond: number;
    successfulTransactions: number;
    failedTransactions: number;
    latency: LatencyStats;
  };
  latencies: number[]; // individual per-transaction latencies in ms
  errors: Array<{ index: number; error: string }>;
}

// ─── Helpers ────────────────────────────────────────────────────

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = Math.ceil((p / 100) * sorted.length) - 1;
  return sorted[Math.max(0, idx)];
}

function computeLatencyStats(latencies: number[]): LatencyStats {
  if (latencies.length === 0) {
    return { min: 0, max: 0, avg: 0, p50: 0, p95: 0, p99: 0 };
  }
  const sorted = [...latencies].sort((a, b) => a - b);
  const sum = sorted.reduce((a, b) => a + b, 0);
  return {
    min: sorted[0]!,
    max: sorted[sorted.length - 1]!,
    avg: sum / sorted.length,
    p50: percentile(sorted, 50),
    p95: percentile(sorted, 95),
    p99: percentile(sorted, 99),
  };
}

// ─── Handlers ───────────────────────────────────────────────────

/**
 * POST /api/performance/benchmark/transfers
 *
 * Runs N sequential transfers across configured account pairs (single-threaded).
 * Measures per-transaction latency and returns aggregated stats.
 */
export async function benchmarkTransfersHandler(
  request: FastifyRequest<{ Body: BenchmarkConfig }>,
  reply: FastifyReply,
) {
  const { userId, accountPairs, numTransactions, amountPerTransaction } = request.body;

  if (!accountPairs || accountPairs.length === 0) {
    return sendError({
      reply,
      statusCode: 400,
      message: "BAD_REQUEST",
      error: "At least one account pair is required",
    });
  }

  if (numTransactions < 1 || numTransactions > 10_000) {
    return sendError({
      reply,
      statusCode: 400,
      message: "BAD_REQUEST",
      error: "numTransactions must be between 1 and 10,000",
    });
  }

  const latencies: number[] = [];
  const errors: Array<{ index: number; error: string }> = [];
  let successCount = 0;

  const overallStart = performance.now();

  for (let i = 0; i < numTransactions; i++) {
    const pair = accountPairs[i % accountPairs.length]!;
    const txStart = performance.now();

    try {
      await walletService.transfer({
        userId: userId as TUserId,
        senderAccountNumber: BigInt(pair.senderAccountNumber) as TBankAccountNumber,
        senderName: pair.senderName,
        receiverAccountNumber: BigInt(pair.receiverAccountNumber) as TBankAccountNumber,
        receiverName: pair.receiverName,
        amount: amountPerTransaction,
      });

      const txEnd = performance.now();
      latencies.push(txEnd - txStart);
      successCount++;
    } catch (err) {
      const txEnd = performance.now();
      latencies.push(txEnd - txStart);
      errors.push({
        index: i,
        error: err instanceof Error ? err.message : "UNKNOWN_ERROR",
      });
    }
  }

  const overallEnd = performance.now();
  const totalTimeMs = overallEnd - overallStart;

  const result: BenchmarkResult = {
    config: {
      numTransactions,
      amountPerTransaction,
      accountPairsCount: accountPairs.length,
    },
    summary: {
      totalTimeMs,
      transactionsPerSecond: successCount / (totalTimeMs / 1000),
      successfulTransactions: successCount,
      failedTransactions: errors.length,
      latency: computeLatencyStats(latencies),
    },
    latencies,
    errors,
  };

  sendSuccess<BenchmarkResult>({
    reply,
    statusCode: 200,
    message: "Benchmark completed",
    data: result,
  });
}

/**
 * GET /api/performance/benchmark/accounts/:userId
 *
 * Returns the user's accounts for configuring the benchmark.
 */
export async function benchmarkAccountsHandler(
  request: FastifyRequest<{ Params: { userId: string } }>,
  reply: FastifyReply,
) {
  try {
    const { userId } = request.params;
    const accounts = await walletService.getUserAccounts(userId as TUserId);

    const accountDTOs = accounts.map((a) => ({
      id: String(a.accountNumber),
      name: a.name,
      accountNumber: String(a.accountNumber),
      balance: a.balance,
    }));

    sendSuccess({
      reply,
      statusCode: 200,
      message: "Accounts fetched",
      data: accountDTOs,
    });
  } catch (error) {
    sendError({
      reply,
      statusCode: 500,
      message: "FAILED_TO_FETCH_ACCOUNTS",
      error: error instanceof Error ? error.message : "INTERNAL_SERVER_ERROR",
    });
  }
}

import type { FastifyInstance } from "fastify";
import { performanceRoutes } from "./definition";
import {
  benchmarkTransfersHandler,
  benchmarkAccountsHandler,
} from "./handler";

export default async function performanceRoute(fastify: FastifyInstance) {
  fastify.post(performanceRoutes.benchmarkTransfers, {
    handler: benchmarkTransfersHandler,
  });

  fastify.get(`${performanceRoutes.benchmarkAccounts}/:userId`, {
    handler: benchmarkAccountsHandler,
  });
}

import { useState, useCallback } from "react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchJSON } from "../lib/queryClient"
import { formatCurrency } from "../lib/utils"

// ─── Types ────────────────────────────────────────────────────

interface BenchmarkAccount {
  id: string
  name: string
  accountNumber: string
  balance: number
}

interface LatencyStats {
  min: number
  max: number
  avg: number
  p50: number
  p95: number
  p99: number
}

interface BenchmarkResult {
  config: {
    numTransactions: number
    amountPerTransaction: number
    accountPairsCount: number
  }
  summary: {
    totalTimeMs: number
    transactionsPerSecond: number
    successfulTransactions: number
    failedTransactions: number
    latency: LatencyStats
  }
  latencies: number[]
  errors: Array<{ index: number; error: string }>
}

// ─── Component ────────────────────────────────────────────────

export default function PerformancePage() {
  const { data: session } = useSession()
  const user = session!.user

  // Config state
  const [numTransactions, setNumTransactions] = useState(100)
  const [amountPerTransaction, setAmountPerTransaction] = useState(1.0)
  const [senderAccount, setSenderAccount] = useState<string>("")
  const [receiverAccount, setReceiverAccount] = useState<string>("")

  // Data state
  const [accounts, setAccounts] = useState<BenchmarkAccount[]>([])
  const [accountsLoading, setAccountsLoading] = useState(true)
  const [accountsError, setAccountsError] = useState<string | null>(null)

  // Benchmark state
  const [running, setRunning] = useState(false)
  const [progress, setProgress] = useState(0)
  const [result, setResult] = useState<BenchmarkResult | null>(null)
  const [benchmarkError, setBenchmarkError] = useState<string | null>(null)

  // Fetch accounts on mount
  const fetchAccounts = useCallback(async () => {
    try {
      setAccountsLoading(true)
      setAccountsError(null)
      const res = await fetchJSON<BenchmarkAccount[]>(
        `/api/performance/benchmark/accounts/${user.id}`,
      )
      setAccounts(res)
      // Auto-select first two accounts if available
      if (res.length >= 2) {
        setSenderAccount(res[0]!.accountNumber)
        setReceiverAccount(res[1]!.accountNumber)
      }
    } catch (err) {
      setAccountsError(err instanceof Error ? err.message : "Failed to load accounts")
    } finally {
      setAccountsLoading(false)
    }
  }, [user.id])

  // Fetch accounts on first render
  useState(() => {
    fetchAccounts()
  })

  // Run benchmark
  const runBenchmark = async () => {
    if (!senderAccount || !receiverAccount) return

    const sender = accounts.find((a) => a.accountNumber === senderAccount)
    const receiver = accounts.find((a) => a.accountNumber === receiverAccount)
    if (!sender || !receiver) return

    setRunning(true)
    setProgress(0)
    setResult(null)
    setBenchmarkError(null)

    // Simulate progress while the long-running request is in flight
    const progressInterval = setInterval(() => {
      setProgress((prev) => Math.min(prev + 1, 95))
    }, 100)

    try {
      const res = await fetchJSON<BenchmarkResult>(
        "/api/performance/benchmark/transfers",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user.id,
            accountPairs: [
              {
                senderAccountNumber: senderAccount,
                senderName: sender.name,
                receiverAccountNumber: receiverAccount,
                receiverName: receiver.name,
              },
            ],
            numTransactions,
            amountPerTransaction,
          }),
        },
      )

      clearInterval(progressInterval)
      setProgress(100)
      setResult(res)
    } catch (err) {
      clearInterval(progressInterval)
      setBenchmarkError(err instanceof Error ? err.message : "Benchmark failed")
    } finally {
      setRunning(false)
    }
  }

  return (
    <>
      <PageHeader
        title="Performance"
        email={user.email}
      />

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-6 space-y-6">
        {/* ─── Configuration ─────────────────────────────────── */}
        <Card>
          <CardHeader className="card-header-accent">
            <CardTitle>Single-Threaded Transfer Benchmark</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Measures max transaction throughput by running sequential transfers across
              configured account pairs. Each transfer is executed one at a time (single-threaded)
              to isolate raw backend performance.
            </p>

            {accountsLoading && (
              <div className="space-y-3">
                <Skeleton className="h-10 w-full rounded-md" />
                <Skeleton className="h-10 w-full rounded-md" />
              </div>
            )}

            {accountsError && (
              <div className="flex items-center gap-2">
                <p className="text-sm text-destructive">{accountsError}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {!accountsLoading && !accountsError && (
              <>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label htmlFor="sender">Sender Account</Label>
                    <select
                      id="sender"
                      value={senderAccount}
                      onChange={(e) => setSenderAccount(e.target.value)}
                      className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <option value="">Select sender</option>
                      {accounts.map((a) => (
                        <option key={a.accountNumber} value={a.accountNumber}>
                          {a.name} ({String(a.accountNumber)}) — {formatCurrency(a.balance)}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="receiver">Receiver Account</Label>
                    <select
                      id="receiver"
                      value={receiverAccount}
                      onChange={(e) => setReceiverAccount(e.target.value)}
                      className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <option value="">Select receiver</option>
                      {accounts.map((a) => (
                        <option key={a.accountNumber} value={a.accountNumber}>
                          {a.name} ({String(a.accountNumber)}) — {formatCurrency(a.balance)}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label htmlFor="num-tx">Number of Transactions</Label>
                    <Input
                      id="num-tx"
                      type="number"
                      min={1}
                      max={10000}
                      value={numTransactions}
                      onChange={(e) => setNumTransactions(Number(e.target.value))}
                    />
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="amount">Amount per Transaction (USD)</Label>
                    <Input
                      id="amount"
                      type="number"
                      step="0.01"
                      min="0.01"
                      value={amountPerTransaction}
                      onChange={(e) => setAmountPerTransaction(Number(e.target.value))}
                    />
                  </div>
                </div>

                <Button
                  onClick={runBenchmark}
                  disabled={running || !senderAccount || !receiverAccount || senderAccount === receiverAccount}
                  className="w-full"
                >
                  {running ? `Running... ${progress}%` : "Run Benchmark"}
                </Button>

                {running && (
                  <div className="w-full bg-secondary rounded-full h-2.5">
                    <div
                      className="bg-primary h-2.5 rounded-full transition-all duration-300"
                      style={{ width: `${progress}%` }}
                    />
                  </div>
                )}
              </>
            )}
          </CardContent>
        </Card>

        {/* ─── Error ─────────────────────────────────────────── */}
        {benchmarkError && (
          <Card className="border-destructive">
            <CardContent className="py-6">
              <p className="text-sm text-destructive text-center">{benchmarkError}</p>
            </CardContent>
          </Card>
        )}

        {/* ─── Results ───────────────────────────────────────── */}
        {result && (
          <>
            {/* Summary Cards */}
            <div className="grid grid-cols-4 gap-4">
              <StatCard
                label="Total Time"
                value={`${(result.summary.totalTimeMs / 1000).toFixed(2)}s`}
              />
              <StatCard
                label="Throughput"
                value={`${result.summary.transactionsPerSecond.toFixed(1)} TPS`}
              />
              <StatCard
                label="Successful"
                value={String(result.summary.successfulTransactions)}
                accent="text-green-600"
              />
              <StatCard
                label="Failed"
                value={String(result.summary.failedTransactions)}
                accent={result.summary.failedTransactions > 0 ? "text-destructive" : undefined}
              />
            </div>

            {/* Latency Stats */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Latency Distribution</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-6 gap-4 text-center">
                  <LatencyStat label="Min" value={result.summary.latency.min} />
                  <LatencyStat label="P50" value={result.summary.latency.p50} />
                  <LatencyStat label="Avg" value={result.summary.latency.avg} />
                  <LatencyStat label="P95" value={result.summary.latency.p95} />
                  <LatencyStat label="P99" value={result.summary.latency.p99} />
                  <LatencyStat label="Max" value={result.summary.latency.max} />
                </div>
              </CardContent>
            </Card>

            {/* Latency Chart */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Latency Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                <LatencyChart latencies={result.latencies} />
              </CardContent>
            </Card>

            {/* Errors */}
            {result.errors.length > 0 && (
              <Card className="border-destructive">
                <CardHeader>
                  <CardTitle className="text-base text-destructive">
                    Errors ({result.errors.length})
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="max-h-48 overflow-y-auto space-y-1">
                    {result.errors.slice(0, 50).map((err) => (
                      <p key={err.index} className="text-xs text-muted-foreground font-mono">
                        TX #{err.index}: {err.error}
                      </p>
                    ))}
                    {result.errors.length > 50 && (
                      <p className="text-xs text-muted-foreground">
                        ... and {result.errors.length - 50} more
                      </p>
                    )}
                  </div>
                </CardContent>
              </Card>
            )}
          </>
        )}
      </main>

      <PageFooter
        left="Wave Performance Monitor"
        right={<span>Single-Threaded Benchmark</span>}
      />
    </>
  )
}

// ─── Sub-components ────────────────────────────────────────────

function StatCard({
  label,
  value,
  accent,
}: {
  label: string
  value: string
  accent?: string
}) {
  return (
    <Card>
      <CardContent className="py-4 text-center">
        <p className="text-xs text-muted-foreground mb-1">{label}</p>
        <p className={`text-2xl font-bold font-mono ${accent ?? "text-foreground"}`}>
          {value}
        </p>
      </CardContent>
    </Card>
  )
}

function LatencyStat({ label, value }: { label: string; value: number }) {
  return (
    <div>
      <p className="text-xs text-muted-foreground mb-1">{label}</p>
      <p className="text-lg font-bold font-mono text-foreground">
        {value < 1 ? `${(value * 1000).toFixed(0)}μs` : `${value.toFixed(1)}ms`}
      </p>
    </div>
  )
}

function LatencyChart({ latencies }: { latencies: number[] }) {
  if (latencies.length === 0) return null

  const maxLatency = Math.max(...latencies)
  const minLatency = Math.min(...latencies)
  const range = maxLatency - minLatency || 1

  // Sample down to at most 200 bars for rendering
  const sampleSize = Math.min(latencies.length, 200)
  const step = Math.max(1, Math.floor(latencies.length / sampleSize))
  const sampled: number[] = []
  for (let i = 0; i < latencies.length; i += step) {
    const slice = latencies.slice(i, i + step)
    sampled.push(slice.reduce((a, b) => a + b, 0) / slice.length)
  }

  return (
    <div className="flex items-end gap-px h-32">
      {sampled.map((lat, i) => {
        const height = ((lat - minLatency) / range) * 100
        return (
          <div
            key={i}
            className="flex-1 bg-primary/80 rounded-t-sm min-w-[2px] transition-all"
            style={{ height: `${Math.max(height, 2)}%` }}
            title={`TX ~${i * step}: ${lat.toFixed(2)}ms`}
          />
        )
      })}
    </div>
  )
}

