+            }
+          });
+
+          res.on("error", (err) => {
+            if (!settled) {
+              settled = true;
+              const establishedMs = performance.now() - connStart;
+              failedConnections++;
+              perConnection.push({
+                index: i,
+                establishedMs,
+                ttfbMs: 0,
+                heartbeatsReceived: 0,
+                error: err.message,
+              });
+              resolve();
+            }
+          });
+
+          // Close connection after duration
+          setTimeout(() => {
+            res.destroy();
+          }, durationMs);
+        },
+      );
+
+      req.on("error", (err) => {
+        if (!settled) {
+          settled = true;
+          const establishedMs = performance.now() - connStart;
+          failedConnections++;
