import { useState, useCallback, useEffect } from "react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchJSON } from "../lib/queryClient"
import { formatCurrency } from "../lib/utils"

// ─── Types ────────────────────────────────────────────────────

interface BenchmarkAccount {
  id: string
  name: string
  accountNumber: string
  balance: number
}

interface LatencyStats {
  min: number
  max: number
  avg: number
  p50: number
  p95: number
  p99: number
}

interface BenchmarkResult {
  config: {
    numTransactions: number
    amountPerTransaction: number
    accountPairsCount: number
    concurrency?: number
  }
  summary: {
    totalTimeMs: number
    transactionsPerSecond: number
    successfulTransactions: number
    failedTransactions: number
    latency: LatencyStats
  }
  latencies: number[]
  errors: Array<{ index: number; error: string }>
}

interface SSEBenchmarkResult {
  config: {
    numConnections: number
    durationMs: number
  }
  summary: {
    successfulConnections: number
    failedConnections: number
    connectionEstablishment: LatencyStats
    timeToFirstByte: LatencyStats
    heartbeatReceived: LatencyStats
  }
  perConnection: Array<{
    index: number
    establishedMs: number
    ttfbMs: number
    heartbeatsReceived: number
    error?: string
  }>
}

// ─── Component ────────────────────────────────────────────────

export default function PerformancePage() {
  const { data: session } = useSession()
  const user = session!.user

  // Shared config state
  const [accounts, setAccounts] = useState<BenchmarkAccount[]>([])
  const [accountsLoading, setAccountsLoading] = useState(true)
  const [accountsError, setAccountsError] = useState<string | null>(null)
  const [senderAccount, setSenderAccount] = useState<string>("")
  const [receiverAccount, setReceiverAccount] = useState<string>("")
  const [numTransactions, setNumTransactions] = useState(100)
  const [amountPerTransaction, setAmountPerTransaction] = useState(1.0)

  // Sequential benchmark state
  const [seqRunning, setSeqRunning] = useState(false)
  const [seqProgress, setSeqProgress] = useState(0)
  const [seqResult, setSeqResult] = useState<BenchmarkResult | null>(null)
  const [seqError, setSeqError] = useState<string | null>(null)

  // Concurrent benchmark state
  const [concRunning, setConcRunning] = useState(false)
  const [concProgress, setConcProgress] = useState(0)
  const [concResult, setConcResult] = useState<BenchmarkResult | null>(null)
  const [concError, setConcError] = useState<string | null>(null)
  const [concurrency, setConcurrency] = useState(2)

  // SSE benchmark state
  const [sseRunning, setSseRunning] = useState(false)
  const [sseProgress, setSseProgress] = useState(0)
  const [sseResult, setSseResult] = useState<SSEBenchmarkResult | null>(null)
  const [sseError, setSseError] = useState<string | null>(null)
  const [sseNumConnections, setSseNumConnections] = useState(100)
  const [sseDuration, setSseDuration] = useState(10)

  // Fetch accounts on mount
  const fetchAccounts = useCallback(async () => {
    try {
      setAccountsLoading(true)
      setAccountsError(null)
      const res = await fetchJSON<BenchmarkAccount[]>(
        `/api/performance/benchmark/accounts/${user.id}`,
      )
      setAccounts(res)
      if (res.length >= 2) {
        setSenderAccount(res[0]!.accountNumber)
        setReceiverAccount(res[1]!.accountNumber)
      }
    } catch (err) {
      setAccountsError(err instanceof Error ? err.message : "Failed to load accounts")
    } finally {
      setAccountsLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  // ─── Sequential Benchmark ──────────────────────────────────

  const runSequential = async () => {
    if (!senderAccount || !receiverAccount) return

    const sender = accounts.find((a) => a.accountNumber === senderAccount)
    const receiver = accounts.find((a) => a.accountNumber === receiverAccount)
    if (!sender || !receiver) return

    setSeqRunning(true)
    setSeqProgress(0)
    setSeqResult(null)
    setSeqError(null)

    const progressInterval = setInterval(() => {
      setSeqProgress((prev) => Math.min(prev + 1, 95))
    }, 100)

    try {
      const res = await fetchJSON<BenchmarkResult>(
        "/api/performance/benchmark/transfers",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user.id,
            accountPairs: [
              {
                senderAccountNumber: senderAccount,
                senderName: sender.name,
                receiverAccountNumber: receiverAccount,
                receiverName: receiver.name,
              },
            ],
            numTransactions,
            amountPerTransaction,
          }),
        },
      )
      clearInterval(progressInterval)
      setSeqProgress(100)
      setSeqResult(res)
    } catch (err) {
      clearInterval(progressInterval)
      setSeqError(err instanceof Error ? err.message : "Benchmark failed")
    } finally {
      setSeqRunning(false)
    }
  }

  // ─── Concurrent Benchmark ──────────────────────────────────

  const runConcurrent = async () => {
    if (!senderAccount || !receiverAccount) return

    const sender = accounts.find((a) => a.accountNumber === senderAccount)
    const receiver = accounts.find((a) => a.accountNumber === receiverAccount)
    if (!sender || !receiver) return

    setConcRunning(true)
    setConcProgress(0)
    setConcResult(null)
    setConcError(null)

    const progressInterval = setInterval(() => {
      setConcProgress((prev) => Math.min(prev + 1, 95))
    }, 100)

    try {
      const res = await fetchJSON<BenchmarkResult>(
        "/api/performance/benchmark/transfers/concurrent",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user.id,
            accountPairs: [
              {
                senderAccountNumber: senderAccount,
                senderName: sender.name,
                receiverAccountNumber: receiverAccount,
                receiverName: receiver.name,
              },
            ],
            numTransactions,
            amountPerTransaction,
            concurrency,
          }),
        },
      )
      clearInterval(progressInterval)
      setConcProgress(100)
      setConcResult(res)
    } catch (err) {
      clearInterval(progressInterval)
      setConcError(err instanceof Error ? err.message : "Benchmark failed")
    } finally {
      setConcRunning(false)
    }
  }

  // ─── SSE Benchmark ─────────────────────────────────────────

  const runSSE = async () => {
    setSseRunning(true)
    setSseProgress(0)
    setSseResult(null)
    setSseError(null)

    const progressInterval = setInterval(() => {
      setSseProgress((prev) => Math.min(prev + 1, 95))
    }, 500)

    try {
      const res = await fetchJSON<SSEBenchmarkResult>(
        "/api/performance/benchmark/sse",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            userId: user.id,
            numConnections: sseNumConnections,
            durationMs: sseDuration * 1000,
          }),
        },
      )
      clearInterval(progressInterval)
      setSseProgress(100)
      setSseResult(res)
    } catch (err) {
      clearInterval(progressInterval)
      setSseError(err instanceof Error ? err.message : "SSE benchmark failed")
    } finally {
      setSseRunning(false)
    }
  }

  return (
    <>
      <PageHeader
        title="Performance"
        email={user.email}
      />

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-6 space-y-6">
        {/* ─── Account Loading ───────────────────────────────── */}
        {accountsLoading && (
          <Card>
            <CardContent className="space-y-3 py-6">
              <Skeleton className="h-10 w-full rounded-md" />
              <Skeleton className="h-10 w-full rounded-md" />
            </CardContent>
          </Card>
        )}

        {accountsError && (
          <Card className="border-destructive">
            <CardContent className="flex items-center gap-2 py-4">
              <p className="text-sm text-destructive">{accountsError}</p>
              <Button variant="outline" size="sm" onClick={fetchAccounts}>
                Retry
              </Button>
            </CardContent>
          </Card>
        )}

        {/* ─── Shared Config ─────────────────────────────────── */}
        {!accountsLoading && !accountsError && (
          <Card>
            <CardHeader className="card-header-accent">
              <CardTitle>Benchmark Configuration</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label htmlFor="sender">Sender Account</Label>
                  <select
                    id="sender"
                    value={senderAccount}
                    onChange={(e) => setSenderAccount(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <option value="">Select sender</option>
                    {accounts.map((a) => (
                      <option key={a.accountNumber} value={a.accountNumber}>
                        {a.name} ({String(a.accountNumber)}) — {formatCurrency(a.balance)}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="receiver">Receiver Account</Label>
                  <select
                    id="receiver"
                    value={receiverAccount}
                    onChange={(e) => setReceiverAccount(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <option value="">Select receiver</option>
                    {accounts.map((a) => (
                      <option key={a.accountNumber} value={a.accountNumber}>
                        {a.name} ({String(a.accountNumber)}) — {formatCurrency(a.balance)}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label htmlFor="num-tx">Number of Transactions</Label>
                  <Input
                    id="num-tx"
                    type="number"
                    min={1}
                    max={10000}
                    value={numTransactions}
                    onChange={(e) => setNumTransactions(Number(e.target.value))}
                  />
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="amount">Amount per Transaction (USD)</Label>
                  <Input
                    id="amount"
                    type="number"
                    step="0.01"
                    min="0.01"
                    value={amountPerTransaction}
                    onChange={(e) => setAmountPerTransaction(Number(e.target.value))}
                  />
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* ═══════════════════════════════════════════════════════ */}
        {/* SECTION 1: SEQUENTIAL BENCHMARK                       */}
        {/* ═══════════════════════════════════════════════════════ */}

        {!accountsLoading && !accountsError && (
          <Card>
            <CardHeader>
              <CardTitle className="text-base">1. Sequential Transfer Benchmark</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Runs transfers one at a time (single-threaded) to measure raw backend performance
                with no contention.
              </p>

              <Button
                onClick={runSequential}
                disabled={seqRunning || !senderAccount || !receiverAccount || senderAccount === receiverAccount}
                className="w-full"
              >
                {seqRunning ? `Running... ${seqProgress}%` : "Run Sequential Benchmark"}
              </Button>

              {seqRunning && (
                <div className="w-full bg-secondary rounded-full h-2.5">
                  <div
                    className="bg-primary h-2.5 rounded-full transition-all duration-300"
                    style={{ width: `${seqProgress}%` }}
                  />
                </div>
              )}

              {seqError && (
                <p className="text-sm text-destructive text-center">{seqError}</p>
              )}

              {seqResult && (
                <BenchmarkResults result={seqResult} />
              )}
            </CardContent>
          </Card>
        )}

        {/* ═══════════════════════════════════════════════════════ */}
        {/* SECTION 2: CONCURRENT BENCHMARK                       */}
        {/* ═══════════════════════════════════════════════════════ */}

        {!accountsLoading && !accountsError && (
          <Card>
            <CardHeader>
              <CardTitle className="text-base">2. Concurrent Transfer Benchmark</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Runs transfers in parallel with controlled concurrency to measure throughput
                under contention. Compare TPS against sequential to find the scaling ceiling.
              </p>

              {/* Concurrency selector */}
              <div className="space-y-1.5">
                <Label>Concurrency Level</Label>
                <div className="flex gap-2">
                  {[1, 2, 5, 10, 20, 50].map((level) => (
                    <Button
                      key={level}
                      variant={concurrency === level ? "default" : "outline"}
                      size="sm"
                      onClick={() => setConcurrency(level)}
                      disabled={concRunning}
                    >
                      {level}
                    </Button>
                  ))}
                </div>
              </div>

              <Button
                onClick={runConcurrent}
                disabled={concRunning || !senderAccount || !receiverAccount || senderAccount === receiverAccount}
                className="w-full"
              >
                {concRunning ? `Running... ${concProgress}%` : "Run Concurrent Benchmark"}
              </Button>

              {concRunning && (
                <div className="w-full bg-secondary rounded-full h-2.5">
                  <div
                    className="bg-primary h-2.5 rounded-full transition-all duration-300"
                    style={{ width: `${concProgress}%` }}
                  />
                </div>
              )}

              {concError && (
                <p className="text-sm text-destructive text-center">{concError}</p>
              )}

              {concResult && (
                <BenchmarkResults result={concResult} />
              )}
            </CardContent>
          </Card>
        )}

        {/* ═══════════════════════════════════════════════════════ */}
        {/* SECTION 3: SSE CONNECTION CAPACITY                    */}
        {/* ═══════════════════════════════════════════════════════ */}

        <Card>
          <CardHeader>
            <CardTitle className="text-base">3. SSE Connection Capacity</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Opens N server-side SSE connections simultaneously to measure connection establishment
              time, time-to-first-byte, and heartbeat delivery. Tests the server's real-time
              infrastructure capacity.
            </p>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="sse-connections">Number of Connections</Label>
                <Input
                  id="sse-connections"
                  type="number"
                  min={1}
                  max={500}
                  value={sseNumConnections}
                  onChange={(e) => setSseNumConnections(Number(e.target.value))}
                />
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="sse-duration">Duration (seconds)</Label>
                <Input
                  id="sse-duration"
                  type="number"
                  min={1}
                  max={60}
                  value={sseDuration}
                  onChange={(e) => setSseDuration(Number(e.target.value))}
                />
              </div>
            </div>

            <Button
              onClick={runSSE}
              disabled={sseRunning}
              className="w-full"
            >
              {sseRunning ? `Running... ${sseProgress}%` : "Run SSE Benchmark"}
            </Button>

            {sseRunning && (
              <div className="w-full bg-secondary rounded-full h-2.5">
                <div
                  className="bg-primary h-2.5 rounded-full transition-all duration-300"
                  style={{ width: `${sseProgress}%` }}
                />
              </div>
            )}

            {sseError && (
              <p className="text-sm text-destructive text-center">{sseError}</p>
            )}

            {sseResult && <SSEResults result={sseResult} />}
          </CardContent>
        </Card>

        {/* ═══════════════════════════════════════════════════════ */}
        {/* SECTION 4: TPS COMPARISON                             */}
        {/* ═══════════════════════════════════════════════════════ */}

        {seqResult && concResult && (
          <ComparisonTable sequential={seqResult} concurrent={concResult} />
        )}
      </main>

      <PageFooter
        left="Wave Performance Monitor"
        right={<span>Benchmarks</span>}
      />
    </>
  )
}

// ─── Shared Results Component ──────────────────────────────────

function BenchmarkResults({ result }: { result: BenchmarkResult }) {
  return (
    <>
      <div className="grid grid-cols-4 gap-4">
        <StatCard
          label="Total Time"
          value={`${(result.summary.totalTimeMs / 1000).toFixed(2)}s`}
        />
        <StatCard
          label="Throughput"
          value={`${result.summary.transactionsPerSecond.toFixed(1)} TPS`}
        />
        <StatCard
          label="Successful"
          value={String(result.summary.successfulTransactions)}
          accent="text-green-600"
        />
        <StatCard
          label="Failed"
          value={String(result.summary.failedTransactions)}
          accent={result.summary.failedTransactions > 0 ? "text-destructive" : undefined}
        />
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Latency Distribution</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-6 gap-4 text-center">
            <LatencyStat label="Min" value={result.summary.latency.min} />
            <LatencyStat label="P50" value={result.summary.latency.p50} />
            <LatencyStat label="Avg" value={result.summary.latency.avg} />
            <LatencyStat label="P95" value={result.summary.latency.p95} />
            <LatencyStat label="P99" value={result.summary.latency.p99} />
            <LatencyStat label="Max" value={result.summary.latency.max} />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Latency Over Time</CardTitle>
        </CardHeader>
        <CardContent>
          <LatencyChart latencies={result.latencies} />
        </CardContent>
      </Card>

      {result.errors.length > 0 && (
        <Card className="border-destructive">
          <CardHeader>
            <CardTitle className="text-base text-destructive">
              Errors ({result.errors.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="max-h-48 overflow-y-auto space-y-1">
              {result.errors.slice(0, 50).map((err) => (
                <p key={err.index} className="text-xs text-muted-foreground font-mono">
                  TX #{err.index}: {err.error}
                </p>
              ))}
              {result.errors.length > 50 && (
                <p className="text-xs text-muted-foreground">
                  ... and {result.errors.length - 50} more
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </>
  )
}

// ─── SSE Results Component ─────────────────────────────────────

function SSEResults({ result }: { result: SSEBenchmarkResult }) {
  const [sortBy, setSortBy] = useState<"establishedMs" | "ttfbMs" | "heartbeatsReceived">("establishedMs")
  const [sortDir, setSortDir] = useState<"asc" | "desc">("asc")

  const sorted = [...result.perConnection].sort((a, b) => {
    const diff = a[sortBy] - b[sortBy]
    return sortDir === "asc" ? diff : -diff
  })

  const toggleSort = (col: typeof sortBy) => {
    if (sortBy === col) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"))
    } else {
      setSortBy(col)
      setSortDir("asc")
    }
  }

  return (
    <>
      <div className="grid grid-cols-4 gap-4">
        <StatCard
          label="Successful"
          value={String(result.summary.successfulConnections)}
          accent="text-green-600"
        />
        <StatCard
          label="Failed"
          value={String(result.summary.failedConnections)}
          accent={result.summary.failedConnections > 0 ? "text-destructive" : undefined}
        />
        <StatCard
          label="Avg Establishment"
          value={`${result.summary.connectionEstablishment.avg.toFixed(0)}ms`}
        />
        <StatCard
          label="Avg TTFB"
          value={`${result.summary.timeToFirstByte.avg.toFixed(0)}ms`}
        />
      </div>

      {/* Establishment Latency */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Connection Establishment Latency</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-6 gap-4 text-center">
            <LatencyStat label="Min" value={result.summary.connectionEstablishment.min} />
            <LatencyStat label="P50" value={result.summary.connectionEstablishment.p50} />
            <LatencyStat label="Avg" value={result.summary.connectionEstablishment.avg} />
            <LatencyStat label="P95" value={result.summary.connectionEstablishment.p95} />
            <LatencyStat label="P99" value={result.summary.connectionEstablishment.p99} />
            <LatencyStat label="Max" value={result.summary.connectionEstablishment.max} />
          </div>
        </CardContent>
      </Card>

      {/* Heartbeat Stats */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Heartbeats Received Per Connection</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-6 gap-4 text-center">
            <LatencyStat label="Min" value={result.summary.heartbeatReceived.min} />
            <LatencyStat label="P50" value={result.summary.heartbeatReceived.p50} />
            <LatencyStat label="Avg" value={result.summary.heartbeatReceived.avg} />
            <LatencyStat label="P95" value={result.summary.heartbeatReceived.p95} />
            <LatencyStat label="P99" value={result.summary.heartbeatReceived.p99} />
            <LatencyStat label="Max" value={result.summary.heartbeatReceived.max} />
          </div>
        </CardContent>
      </Card>

      {/* Per-Connection Detail */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">
            Per-Connection Detail ({result.perConnection.length} connections)
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="max-h-96 overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-background">
                <tr className="border-b border-border">
                  <th className="text-left py-2 px-3 font-medium text-muted-foreground">#</th>
                  <th
                    className="text-right py-2 px-3 font-medium text-muted-foreground cursor-pointer hover:text-foreground"
                    onClick={() => toggleSort("establishedMs")}
                  >
                    Establishment {sortBy === "establishedMs" ? (sortDir === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th
                    className="text-right py-2 px-3 font-medium text-muted-foreground cursor-pointer hover:text-foreground"
                    onClick={() => toggleSort("ttfbMs")}
                  >
                    TTFB {sortBy === "ttfbMs" ? (sortDir === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th
                    className="text-right py-2 px-3 font-medium text-muted-foreground cursor-pointer hover:text-foreground"
                    onClick={() => toggleSort("heartbeatsReceived")}
                  >
                    Heartbeats {sortBy === "heartbeatsReceived" ? (sortDir === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th className="text-left py-2 px-3 font-medium text-muted-foreground">Status</th>
                </tr>
              </thead>
              <tbody>
                {sorted.slice(0, 100).map((conn) => (
                  <tr key={conn.index} className="border-b border-border/50">
                    <td className="py-1.5 px-3 font-mono text-muted-foreground">{conn.index + 1}</td>
                    <td className="py-1.5 px-3 text-right font-mono">{conn.establishedMs.toFixed(1)}ms</td>
                    <td className="py-1.5 px-3 text-right font-mono">{conn.ttfbMs.toFixed(1)}ms</td>
                    <td className="py-1.5 px-3 text-right font-mono">{conn.heartbeatsReceived}</td>
                    <td className="py-1.5 px-3">
                      {conn.error ? (
                        <span className="text-destructive text-xs">{conn.error}</span>
                      ) : (
                        <span className="text-green-600 text-xs">OK</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {sorted.length > 100 && (
              <p className="text-xs text-muted-foreground text-center py-2">
                Showing 100 of {sorted.length} connections
              </p>
            )}
          </div>
        </CardContent>
      </Card>
    </>
  )
}

// ─── Comparison Table ──────────────────────────────────────────

function ComparisonTable({
  sequential,
  concurrent,
}: {
  sequential: BenchmarkResult
  concurrent: BenchmarkResult
}) {
  const rows = [
    {
      label: "TPS",
      seq: sequential.summary.transactionsPerSecond.toFixed(1),
      conc: concurrent.summary.transactionsPerSecond.toFixed(1),
      delta: ((concurrent.summary.transactionsPerSecond / sequential.summary.transactionsPerSecond - 1) * 100).toFixed(1),
    },
    {
      label: "Total Time",
      seq: `${(sequential.summary.totalTimeMs / 1000).toFixed(2)}s`,
      conc: `${(concurrent.summary.totalTimeMs / 1000).toFixed(2)}s`,
      delta: ((1 - concurrent.summary.totalTimeMs / sequential.summary.totalTimeMs) * 100).toFixed(1),
    },
    {
      label: "P50 Latency",
      seq: formatLatency(sequential.summary.latency.p50),
      conc: formatLatency(concurrent.summary.latency.p50),
      delta: ((1 - concurrent.summary.latency.p50 / sequential.summary.latency.p50) * 100).toFixed(1),
    },
    {
      label: "P95 Latency",
      seq: formatLatency(sequential.summary.latency.p95),
      conc: formatLatency(concurrent.summary.latency.p95),
      delta: ((1 - concurrent.summary.latency.p95 / sequential.summary.latency.p95) * 100).toFixed(1),
    },
    {
      label: "P99 Latency",
      seq: formatLatency(sequential.summary.latency.p99),
      conc: formatLatency(concurrent.summary.latency.p99),
      delta: ((1 - concurrent.summary.latency.p99 / sequential.summary.latency.p99) * 100).toFixed(1),
    },
    {
      label: "Success Rate",
      seq: `${((sequential.summary.successfulTransactions / sequential.config.numTransactions) * 100).toFixed(1)}%`,
      conc: `${((concurrent.summary.successfulTransactions / concurrent.config.numTransactions) * 100).toFixed(1)}%`,
      delta: null,
    },
  ]

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">TPS Comparison: Sequential vs Concurrent</CardTitle>
      </CardHeader>
      <CardContent>
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-border">
              <th className="text-left py-2 px-3 font-medium text-muted-foreground">Metric</th>
              <th className="text-right py-2 px-3 font-medium text-muted-foreground">Sequential</th>
              <th className="text-right py-2 px-3 font-medium text-muted-foreground">
                Concurrent (c={concurrent.config.concurrency})
              </th>
              <th className="text-right py-2 px-3 font-medium text-muted-foreground">Delta</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.label} className="border-b border-border/50">
                <td className="py-2 px-3 font-medium">{row.label}</td>
                <td className="py-2 px-3 text-right font-mono">{row.seq}</td>
                <td className="py-2 px-3 text-right font-mono">{row.conc}</td>
                <td className="py-2 px-3 text-right font-mono">
                  {row.delta !== null ? (
                    <span className={Number(row.delta) >= 0 ? "text-green-600" : "text-destructive"}>
                      {Number(row.delta) >= 0 ? "+" : ""}{row.delta}%
                    </span>
                  ) : (
                    <span className="text-muted-foreground">—</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </CardContent>
    </Card>
  )
}

// ─── Utility Components ────────────────────────────────────────

function formatLatency(ms: number): string {
  return ms < 1 ? `${(ms * 1000).toFixed(0)}μs` : `${ms.toFixed(1)}ms`
}

function StatCard({
  label,
  value,
  accent,
}: {
  label: string
  value: string
  accent?: string
}) {
  return (
    <Card>
      <CardContent className="py-4 text-center">
        <p className="text-xs text-muted-foreground mb-1">{label}</p>
        <p className={`text-2xl font-bold font-mono ${accent ?? "text-foreground"}`}>
          {value}
        </p>
      </CardContent>
    </Card>
  )
}

function LatencyStat({ label, value }: { label: string; value: number }) {
  return (
    <div>
      <p className="text-xs text-muted-foreground mb-1">{label}</p>
      <p className="text-lg font-bold font-mono text-foreground">
        {value < 1 ? `${(value * 1000).toFixed(0)}μs` : `${value.toFixed(1)}ms`}
      </p>
    </div>
  )
}

function LatencyChart({ latencies }: { latencies: number[] }) {
  if (latencies.length === 0) return null

  const maxLatency = Math.max(...latencies)
  const minLatency = Math.min(...latencies)
  const range = maxLatency - minLatency || 1

  const sampleSize = Math.min(latencies.length, 200)
  const step = Math.max(1, Math.floor(latencies.length / sampleSize))
  const sampled: number[] = []
  for (let i = 0; i < latencies.length; i += step) {
    const slice = latencies.slice(i, i + step)
    sampled.push(slice.reduce((a, b) => a + b, 0) / slice.length)
  }

  return (
    <div className="flex items-end gap-px h-32">
      {sampled.map((lat, i) => {
        const height = ((lat - minLatency) / range) * 100
        return (
          <div
            key={i}
            className="flex-1 bg-primary/80 rounded-t-sm min-w-[2px] transition-all"
            style={{ height: `${Math.max(height, 2)}%` }}
            title={`TX ~${i * step}: ${lat.toFixed(2)}ms`}
          />
        )
      })}
    </div>
  )
}

