import type { TBankAccountNumber, TLedgerEntryId, TTransactionId, TUserId } from "@/types";

// ── Account ──────────────────────────────────────────
export interface IAccountDTO {
  name: string;
  userId: TUserId;
  accountNumber: TBankAccountNumber;
  balance: number;
  createdAt: Date;
  updatedAt: Date | null;
}

