import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import type { IOutboxEntry, IOutboxRepository } from "../repository";
import type { IKafkaService } from "@/modules/kafka";

const findUnpublishedMock = vi.fn();
const markAsPublishedMock = vi.fn();
const kafkaPublishMock = vi.fn();

vi.mock("../repository", () => ({
  OutboxRepository: function OutboxRepositoryMock(this: {
    findUnpublished: typeof findUnpublishedMock;
    markAsPublished: typeof markAsPublishedMock;
  }) {
    this.findUnpublished = findUnpublishedMock;
    this.markAsPublished = markAsPublishedMock;
  },
}));

vi.mock("@/modules/kafka", () => ({
  kafkaRPCClient: {
    connect: vi.fn(),
    disconnect: vi.fn(),
    publishTransactionEvent: kafkaPublishMock,
  },
}));

import { OutboxReplayService } from "./outbox-replay.service";

const makeEntry = (overrides: Partial<IOutboxEntry> = {}): IOutboxEntry => ({
  id: "ob_1",
  transactionId: "tx_1",
  eventType: "transaction.created",
  payload: {
    eventType: "transaction.created",
    transactionId: "tx_1",
    userId: "user_1",
    senderAccountNumber: "1111111111",
    receiverAccountNumber: "2222222222",
    amount: "100000",
    senderName: "Alice",
    receiverName: "Bob",
    status: "pending",
    timestamp: new Date().toISOString(),
  },
  published: false,
  publishedAt: null,
  createdAt: new Date(),
  updatedAt: new Date(),
  ...overrides,
});

describe("OutboxReplayService", () => {
  let service: OutboxReplayService;

  beforeEach(() => {
    vi.clearAllMocks();
    findUnpublishedMock.mockResolvedValue([]);
    markAsPublishedMock.mockResolvedValue(undefined);
    kafkaPublishMock.mockResolvedValue(undefined);
    service = new OutboxReplayService(undefined, undefined, 1_000_000, 100);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    service.stopReplayLoop();
  });

  describe("startReplayLoop", () => {
    it("should fetch unpublished entries immediately on start", async () => {
      findUnpublishedMock.mockResolvedValue([makeEntry()]);

      service.startReplayLoop();
      await vi.waitFor(() => {
        expect(findUnpublishedMock).toHaveBeenCalledTimes(1);
      });
    });

    it("should publish each unpublished entry to Kafka", async () => {
      findUnpublishedMock.mockResolvedValue([makeEntry()]);

      service.startReplayLoop();
      await vi.waitFor(() => {
        expect(kafkaPublishMock).toHaveBeenCalledTimes(1);
      });
    });

    it("should mark entries as published after successful publish", async () => {
      findUnpublishedMock.mockResolvedValue([makeEntry()]);

      service.startReplayLoop();
      await vi.waitFor(() => {
        expect(markAsPublishedMock).toHaveBeenCalledWith("tx_1");
      });
    });

    it("should not throw when a single publish fails", async () => {
      const entry1 = makeEntry({ id: "ob_1", transactionId: "tx_1" });
      const entry2 = makeEntry({ id: "ob_2", transactionId: "tx_2" });
      kafkaPublishMock.mockRejectedValueOnce(new Error("Kafka down"));
      findUnpublishedMock.mockResolvedValue([entry1, entry2]);

      service.startReplayLoop();
      await vi.waitFor(() => {
        expect(kafkaPublishMock).toHaveBeenCalledTimes(2);
      });
    });

    it("should not start a second interval if already running", async () => {
      findUnpublishedMock.mockResolvedValue([makeEntry()]);

      service.startReplayLoop();
      service.startReplayLoop();
      await vi.waitFor(() => {
