           const updatedTransaction = await this.transactionRepo.update({
             ...transaction,
             status: "success",
             updatedAt: new Date(),
           });

           const serializableResult = {
             ...updatedTransaction,
             amount: updatedTransaction.amount.toString(),
             senderAccountNumber: updatedTransaction.senderAccountNumber.toString(),
             receiverAccountNumber: updatedTransaction.receiverAccountNumber.toString(),
           };

           await this.idempotencyRepo.updateStatus(idempotencyKey, "completed", serializableResult);

           return updatedTransaction;
         } catch (err) {
           await this.idempotencyRepo.updateStatus(idempotencyKey, "failed", undefined, (err as Error).message);
           throw err;
         }
       },
       errorMessage: "FAILED_TO_TRANSFER",
     });
   }

   listTransactions(userId: TUserId): Promise<ITransaction[]> {
     return tryCatch({
       ctx: async () => {
         const transactions = await this.transactionRepo.findByUserId(userId);
         return transactions;
       },
       errorMessage: "FAILED_TO_LIST_TRANSACTIONS",
     });
   }

   queryTransactions(
     query: TTransactionQuery,
     userId: TUserId,
   ): Promise<ITransaction[]> {
     return tryCatch({
       ctx: async () => {
         switch (query.status) {
           case "success": {
             const successfulTransactions =
               await this.transactionRepo.successfulTransactions({
                 userId,
                 dateRange: query.dateRange,
               });
             return successfulTransactions;
           }

           case "failed": {
             const failedTransactions =
               await this.transactionRepo.failedTransactions({
                 userId,
                 dateRange: query.dateRange,
               });
             return failedTransactions;
           }

           default:
             throw new Error(
               "Invalid status value. Allowed values are 'success' or 'failed'.",
             );
         }
       },
       errorMessage: "FAILED_TO_QUERY_TRANSACTIONS",
     });
   }

   // ───────────────────────────────────────────────────────────────────
   // Ledger Operations
   // ───────────────────────────────────────────────────────────────────

   getLedgerEntries(transactionId: TTransactionId): Promise<ILedger[]> {
     return tryCatch({
       ctx: async () => {
         return await this.ledgerRepo.findByTransactionId(transactionId);
       },
       errorMessage: "FAILED_TO_GET_LEDGER_ENTRIES",
     });
   }
 }

